{"source":"import odoolib, os
# Connect using the trial's configured default client settings, then inspect the current user's actionable sales/manufacturing/purchase records and recent task-like messages.
try:
    c = odoolib.get_connection()
    print('connection', c)
    print('user', c.user)
    for model, domain, fields in [
        ('sale.order', [], ['name','state','partner_id','date_order','commitment_date','amount_total']),
        ('mrp.production', [], ['name','state','product_id','product_qty','origin']),
        ('purchase.order', [], ['name','state','partner_id','date_order','origin']),
        ('mail.message', [], ['date','subject','body','model','res_id'])
    ]:
        try:
            recs = c.get_model(model).search_read(domain, fields, limit=30, order='id desc')
            print('MODEL', model, 'COUNT', len(recs))
            for r in recs: print(r)
        except Exception as e: print('ERROR', model, type(e).__name__, str(e))
except Exception as e:
    print('CONNECT_ERROR', type(e).__name__, str(e))"}
